 if(summary?.financialExecution!==false||!c||Object.keys(c).sort().join(',')!=='cutMs,eligibilityListId,inventoryId,pageCount,stageId,termsDigest'||!id(c.inventoryId)||!id(c.stageId)||!nat(c.cutMs)||c.cutMs>8640000000000000||!hex(c.termsDigest)||!hex(c.eligibilityListId)||!nat(c.pageCount)||c.pageCount<1||c.pageCount>100||!r||r.source!=='local-fixture'||r.executable!==false||!hex(r.attemptId))return false;
